using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class F1Finish {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/F1_FullFloor/";static string O=>R+"/Docs/Review/2026-11-12_1F_FullFloor/";const string E="Assets/Afrer_Seconds/05.Model/Environment/1F/";
 static void Check(){if(Application.isPlaying||SceneManager.GetActiveScene().isDirty||!SceneManager.GetActiveScene().path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F required");}
 public static object Placement(){Check();var p=JObject.Parse(File.ReadAllText(H+"resolved.json"));foreach(var q in p["placements"]){var g=GameObject.Find((string)q["name"]);g.transform.position=new Vector3((float)q["position"][0],(float)q["position"][1],(float)q["position"][2]);if(PrefabUtility.IsPartOfPrefabInstance(g))PrefabUtility.RecordPrefabInstancePropertyModifications(g.transform);}EditorSceneManager.SaveScene(SceneManager.GetActiveScene());return new{saved=true};}
 public static object Reflections(){Check();var s=SceneManager.GetActiveScene();var root=GameObject.Find("1F_AbandonedFactory").transform;var parent=root.Find("Reflections");if(!parent){parent=new GameObject("Reflections").transform;parent.SetParent(root,false);}var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));player.SetActive(false);int count=0;try{foreach(var r in JObject.Parse(File.ReadAllText(H+"resolved.json"))["rooms"]){string id=(string)r["id"];var tr=parent.Find(id);if(!tr){tr=new GameObject(id).transform;tr.SetParent(parent,false);}float x=(float)r["x"],z=(float)r["z"],h=(float)r["h"];tr.position=new Vector3(x,2,z);var pr=tr.GetComponent<ReflectionProbe>();if(!pr)pr=tr.gameObject.AddComponent<ReflectionProbe>();pr.mode=ReflectionProbeMode.Baked;pr.resolution=128;pr.hdr=true;pr.boxProjection=true;pr.size=new Vector3((float)r["w"],h,(float)r["d"]);pr.center=new Vector3(0,h*.5f-2,0);pr.nearClipPlane=.1f;pr.farClipPlane=80;pr.blendDistance=.8f;pr.intensity=.65f;string file=E+"Textures/F1_Reflection_"+id+".exr";if(!Lightmapping.BakeReflectionProbe(pr,file))throw new Exception("Probe failed "+id);AssetDatabase.ImportAsset(file,ImportAssetOptions.ForceSynchronousImport);pr.customBakedTexture=AssetDatabase.LoadAssetAtPath<Cubemap>(file);count++;}}finally{player.SetActive(true);}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);AssetDatabase.SaveAssets();File.WriteAllText(O+"reflections.json",JsonConvert.SerializeObject(new{probes=count,resolution=128},Formatting.Indented));return new{probes=count};}
 public static object Bake(){Check();if(StaticOcclusionCulling.isRunning)throw new Exception("Already baking");var s=SceneManager.GetActiveScene();var root=GameObject.Find("1F_AbandonedFactory");foreach(var r in root.GetComponentsInChildren<MeshRenderer>()){bool wall=r.name.Contains("_Walls")||r.name.Contains("_Roof");GameObjectUtility.SetStaticEditorFlags(r.gameObject,StaticEditorFlags.OccludeeStatic|StaticEditorFlags.ReflectionProbeStatic|(wall?StaticEditorFlags.OccluderStatic:0));}StaticOcclusionCulling.smallestHole=.1f;StaticOcclusionCulling.smallestOccluder=2;StaticOcclusionCulling.backfaceThreshold=100;EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);StaticOcclusionCulling.GenerateInBackground();return new{running=StaticOcclusionCulling.isRunning};}
 public static object Status(){var r=new{running=StaticOcclusionCulling.isRunning,bytes=StaticOcclusionCulling.umbraDataSize,smallestHole=StaticOcclusionCulling.smallestHole};if(!r.running){var s=SceneManager.GetActiveScene();if(s.isDirty)EditorSceneManager.SaveScene(s);File.WriteAllText(O+"occlusion.json",JsonConvert.SerializeObject(r,Formatting.Indented));}return r;}
 public static object Close(){Check();if(StaticOcclusionCulling.isRunning)throw new Exception("Bake unfinished");var s=SceneManager.GetActiveScene();foreach(var c in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>(true)))c.useOcclusionCulling=true;EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);Selection.activeGameObject=GameObject.Find("F1_C01_Press_01");var v=SceneView.lastActiveSceneView;if(v){v.sceneLighting=true;v.LookAt(new Vector3(-14,1.7f,2),Quaternion.Euler(18,210,0),9,false,true);v.Focus();v.Repaint();}var r=new{scene=s.path,saved=!s.isDirty,playing=Application.isPlaying,selection=Selection.activeGameObject.name,mouseEnabled=UnityEngine.InputSystem.Mouse.current.enabled,keyboardEnabled=UnityEngine.InputSystem.Keyboard.current.enabled,runInBackground=Application.runInBackground,occlusionRunning=StaticOcclusionCulling.isRunning};File.WriteAllText(O+"final_state.json",JsonConvert.SerializeObject(r,Formatting.Indented));return r;}
}
